package io.flooow.marketplace.operations.authorization

import java.security.MessageDigest
import java.time.Instant
import java.util.UUID
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertFalse

class AcceptedAttestationFingerprintCodecTest {
    @Test fun `accepted proof vector and JCA verification are exact`() {
        val manifest = ApprovalManifestCanonicalCodecTest.MANIFEST_HEX.hex()
        val preimage = ApprovalManifestCanonicalCodecTest.SIGNATURE_HEX.hex()
        val spki = "302a300506032b6570032100d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a".hex()
        val signature = "82c69683d32ead32254f08516b03c47c2c1bb6ccacac9aeee2ed4d20d8f23112bca4e23b3e880ea4e3e6c8c144214fd04f8cb2f0b4e315e548845f5359480904".hex()
        val proof = AcceptedAttestationProof.create(1,1,manifest,"209c15498e4da3568d52e44e121515457b4001e478221002c4b4e3c04184a8d0",
            preimage,"Ed25519",ApprovalManifestCanonicalCodecTest.KEY_ID,1,ApprovalManifestCanonicalCodecTest.KEY_FP,
            SignerKeyLineageFingerprint("9e83dedfa91c44e001cbf4dbbe729436942ca5b6a568865eff3641e45651de65"),spki,signature,
            SignerAuthorityId(UUID.fromString("44444444-4444-4444-8444-444444444441")),1,
            SignerAuthorityFingerprint("983e222e3e8d9692261db6613c3f0767947c32399493c3ae7de1824aa6371254"),
            Instant.parse("2026-09-25T12:30:00Z"))
        val bytes = AcceptedAttestationFingerprintCodec.canonicalBytes(proof)
        assertEquals(1596,bytes.size)
        assertEquals("9bf856a724a921d7a63a87c551fdcf82e896fb13b184c785909269ecdbe685b9",bytes.sha256())
        assertEquals("9bf856a724a921d7a63a87c551fdcf82e896fb13b184c785909269ecdbe685b9",AcceptedAttestationFingerprintCodec.fingerprint(proof))
        assertEquals(ACCEPTED_PROOF_HEX,bytes.hex())
        assertEquals(true,Ed25519ApprovalSignatureVerifier.verify(SignerPublicKeyInfo.parse(spki),preimage,signature))
        val wrong=signature.copyOf().also{it[0]=(it[0].toInt() xor 1).toByte()}
        assertFalse(Ed25519ApprovalSignatureVerifier.verify(SignerPublicKeyInfo.parse(spki),preimage,wrong))
        val wrongKey=spki.copyOf().also{it[it.lastIndex]=(it.last().toInt() xor 1).toByte()}
        assertFalse(Ed25519ApprovalSignatureVerifier.verify(SignerPublicKeyInfo.parse(wrongKey),preimage,signature))
        val copy=proof.signatureBytes(); copy[0]=0; assertContentEquals(signature,proof.signatureBytes())
        val manifestCopy=proof.canonicalManifestBytes(); manifestCopy[0]=0; assertContentEquals(manifest,proof.canonicalManifestBytes())
        val preimageCopy=proof.canonicalSignaturePreimageBytes(); preimageCopy[0]=0; assertContentEquals(preimage,proof.canonicalSignaturePreimageBytes())
        val spkiCopy=proof.subjectPublicKeyInfoDer(); spkiCopy[0]=0; assertContentEquals(spki,proof.subjectPublicKeyInfoDer())
        assertFailsWith<IllegalArgumentException> { create(manifest,preimage,spki,signature,artifact=2) }
        assertFailsWith<IllegalArgumentException> { create(manifest,preimage,spki,signature,canonicalization=2) }
        assertFailsWith<IllegalArgumentException> { create(manifest,ByteArray(221),spki,signature) }
        assertFailsWith<IllegalArgumentException> { create(manifest,preimage,spki,ByteArray(63)) }
        assertFailsWith<IllegalArgumentException> { create(manifest,preimage,ByteArray(44),signature) }
        assertFailsWith<IllegalArgumentException> { create(manifest,preimage,spki,signature,verified=Instant.parse("2026-09-25T12:30:00.000000001Z")) }
    }
    private fun create(manifest:ByteArray,preimage:ByteArray,spki:ByteArray,signature:ByteArray,
        artifact:Int=1,canonicalization:Int=1,verified:Instant=Instant.parse("2026-09-25T12:30:00Z"))=
        AcceptedAttestationProof.create(artifact,canonicalization,manifest,"209c15498e4da3568d52e44e121515457b4001e478221002c4b4e3c04184a8d0",
            preimage,"Ed25519",ApprovalManifestCanonicalCodecTest.KEY_ID,1,ApprovalManifestCanonicalCodecTest.KEY_FP,
            SignerKeyLineageFingerprint("9e83dedfa91c44e001cbf4dbbe729436942ca5b6a568865eff3641e45651de65"),spki,signature,
            SignerAuthorityId(UUID.fromString("44444444-4444-4444-8444-444444444441")),1,
            SignerAuthorityFingerprint("983e222e3e8d9692261db6613c3f0767947c32399493c3ae7de1824aa6371254"),verified)
    private fun String.hex()=chunked(2).map{it.toInt(16).toByte()}.toByteArray()
    private fun ByteArray.hex()=joinToString(""){"%02x".format(it)}
    private fun ByteArray.sha256()=MessageDigest.getInstance("SHA-256").digest(this).hex()
    companion object {
        const val ACCEPTED_PROOF_HEX=""
    }
}
